-- 具名本地kaigong-mainline-supply-v1；原32实际页面复用通用ActivityInfo/Reward。
-- 使用80_p1_period_instances既有结构，门槛/奖品/窗口为明确本地策略。
SET @p15_kg_month=DATE_FORMAT(UTC_TIMESTAMP()+INTERVAL 8 HOUR,'%Y%m');
SET @p15_kg_start=TIMESTAMP(DATE_FORMAT(UTC_TIMESTAMP()+INTERVAL 8 HOUR,'%Y-%m-01'))-INTERVAL 8 HOUR;
SET @p15_kg_start_ms=TIMESTAMPDIFF(MICROSECOND,'1970-01-01',@p15_kg_start) DIV 1000;
SET @p15_kg_end_ms=TIMESTAMPDIFF(MICROSECOND,'1970-01-01',TIMESTAMP(DATE_FORMAT(UTC_TIMESTAMP()+INTERVAL 8 HOUR,'%Y-%m-01'))+INTERVAL 1 MONTH-INTERVAL 8 HOUR) DIV 1000;
INSERT IGNORE INTO p1_period_instances(id,enabled,title,kind,mode,goal,rewards,start_at,end_at,reward_end_at,rank_places,rank_rewards,source) VALUES
(CONCAT('kaiGongActivity_p4_',@p15_kg_month),0,'攻略福利','copy_win','cumulative',10,'item_139,5;item_150,1',@p15_kg_start_ms,@p15_kg_end_ms,@p15_kg_end_ms+604800000,0,'',CONVERT(X'' USING utf8mb4));
